#pragma once
// Coupon schedules: the list of accrual dates of a swap leg or a bond.
//
// Dates are generated by stepping whole multiples of the tenor away from an
// anchor (the maturity for "backward" generation, so that any irregular stub
// lands at the front) and are then rolled onto business days.  The algorithm
// mirrors QuantLib's Schedule so that both libraries produce identical dates.
#include <cstddef>
#include <vector>

#include "mcb/core/calendar.hpp"
#include "mcb/core/date.hpp"

namespace mcb {

enum class DateGeneration {
  Backward,  // from termination back to effective (short front stub)
  Forward,   // from effective forward to termination (short back stub)
  Zero       // a single period
};

struct ScheduleSpec {
  Date effective;
  Date termination;
  Period tenor{1, TimeUnit::Years};
  Calendar calendar;
  BusinessDayConvention convention = BusinessDayConvention::ModifiedFollowing;
  BusinessDayConvention terminationConvention = BusinessDayConvention::ModifiedFollowing;
  DateGeneration rule = DateGeneration::Backward;
  bool endOfMonth = false;
};

class Schedule {
 public:
  Schedule() = default;
  explicit Schedule(std::vector<Date> dates) : dates_(std::move(dates)) {}
  static Schedule make(const ScheduleSpec& spec);

  const std::vector<Date>& dates() const { return dates_; }
  std::size_t size() const { return dates_.size(); }
  std::size_t periods() const { return dates_.empty() ? 0 : dates_.size() - 1; }
  Date operator[](std::size_t i) const { return dates_.at(i); }
  Date front() const { return dates_.front(); }
  Date back() const { return dates_.back(); }

 private:
  std::vector<Date> dates_;
};

}  // namespace mcb
